local GrainFarmer = {}
local PRODUCTS = {
    barley_crop = { name = "Ječmen", barleySeedCost = 1, waterCost = 1, time = 3, cost = 12, yield = 30, description = "Ječmen za pivo in kruh." },
    wheat_crop = { name = "Pšenica", wheatSeedCost = 1, waterCost = 1, time = 4, cost = 18, yield = 40, prestige = 1, description = "Pšenica za beli kruh." },
    rye_crop = { name = "Rž", ryeSeedCost = 1, waterCost = 1, time = 3, cost = 15, yield = 35, prestige = 1, description = "Rž za rženi kruh." },
    oats_crop = { name = "Oves", oatSeedCost = 1, waterCost = 1, time = 3, cost = 20, yield = 50, prestige = 2, happiness = 1, description = "Oves za konje in kaše." },
    silver_sheaf_grain = { name = "Srebrni snop žita", wheatSeedCost = 1, silverCost = 1, waterCost = 1, time = 7, cost = 80, yield = 70, prestige = 6, happiness = 2, description = "Srebrni snop žita za plemiče." },
    royal_grand_harvest = { name = "Kraljevski veliki žetev", wheatSeedCost = 2, barleySeedCost = 1, goldCost = 1, silverCost = 1, jewelCost = 1, waterCost = 2, time = 12, cost = 600, yield = 100, prestige = 28, happiness = 7, description = "Velika kraljevska žetev z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Kmetijska postaja", cost = { gold = 200, wood = 100, stone = 100 }, upkeep = 4, qualityBonus = 5 },
    grain_farm = { name = "Žitna kmetija", cost = { gold = 700, wood = 200, stone = 250, water = 10 }, upkeep = 16, qualityBonus = 18 },
    threshing_barn = { name = "Mlatilnica", cost = { gold = 1800, wood = 350, stone = 500, silver = 25, iron = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_grain_atelier = { name = "Kraljevski atelje žita", cost = { gold = 7500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 40 },
}
GrainFarmer.barleySeedStock = 24; GrainFarmer.wheatSeedStock = 22; GrainFarmer.ryeSeedStock = 18; GrainFarmer.oatSeedStock = 18; GrainFarmer.waterStock = 18; GrainFarmer.silverStock = 8; GrainFarmer.goldStock = 6; GrainFarmer.jewelStock = 6
GrainFarmer.productStock = {}; GrainFarmer.buildings = {}; GrainFarmer.maker = nil; GrainFarmer.activeMaking = {}; GrainFarmer.totalProducts = 0; GrainFarmer.dayTimer = 0
function GrainFarmer.init() GrainFarmer.barleySeedStock=24; GrainFarmer.wheatSeedStock=22; GrainFarmer.ryeSeedStock=18; GrainFarmer.oatSeedStock=18; GrainFarmer.waterStock=18; GrainFarmer.silverStock=8; GrainFarmer.goldStock=6; GrainFarmer.jewelStock=6; GrainFarmer.productStock={}; GrainFarmer.buildings={}; GrainFarmer.maker=nil; GrainFarmer.activeMaking={}; GrainFarmer.totalProducts=0; GrainFarmer.dayTimer=0; print("[GrainFarmer] Royal Grain Farmer System initialized (6 products, 4 buildings)") end
function GrainFarmer.hireMaker(n,s) s=s or math.random(45,85); local c=420+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainFarmer.maker={name=n or ("Kmet "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kmet najet: %s (spretnost: %d)",GrainFarmer.maker.name,s),"success") end; return true end
function GrainFarmer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainFarmer.build(id) local ok,e=GrainFarmer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainFarmer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainFarmer.getQualityBonus() local b=0; for _,bd in ipairs(GrainFarmer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainFarmer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.barleySeedCost and GrainFarmer.barleySeedStock<(d.barleySeedCost or 0) then return false,"Premalo ječmena" end; if d.wheatSeedCost and GrainFarmer.wheatSeedStock<(d.wheatSeedCost or 0) then return false,"Premalo pšenice" end; if d.ryeSeedCost and GrainFarmer.ryeSeedStock<(d.ryeSeedCost or 0) then return false,"Premalo rži" end; if d.oatSeedCost and GrainFarmer.oatSeedStock<(d.oatSeedCost or 0) then return false,"Premalo ovsa" end; if d.waterCost and GrainFarmer.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and GrainFarmer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainFarmer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainFarmer.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #GrainFarmer.buildings==0 then return false,"Potrebna delavnica" end; if not GrainFarmer.maker then return false,"Potreben kmet" end; return true end
function GrainFarmer.make(pt,qty) qty=qty or 10; local ok,e=GrainFarmer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.barleySeedCost then GrainFarmer.barleySeedStock=GrainFarmer.barleySeedStock-d.barleySeedCost*qty end; if d.wheatSeedCost then GrainFarmer.wheatSeedStock=GrainFarmer.wheatSeedStock-d.wheatSeedCost*qty end; if d.ryeSeedCost then GrainFarmer.ryeSeedStock=GrainFarmer.ryeSeedStock-d.ryeSeedCost*qty end; if d.oatSeedCost then GrainFarmer.oatSeedStock=GrainFarmer.oatSeedStock-d.oatSeedCost*qty end; if d.waterCost then GrainFarmer.waterStock=GrainFarmer.waterStock-d.waterCost*qty end; if d.silverCost then GrainFarmer.silverStock=GrainFarmer.silverStock-d.silverCost*qty end; if d.goldCost then GrainFarmer.goldStock=GrainFarmer.goldStock-d.goldCost*qty end; if d.jewelCost then GrainFarmer.jewelStock=GrainFarmer.jewelStock-d.jewelCost*qty end; local t=d.time; if GrainFarmer.maker then t=math.max(1,t-math.floor(GrainFarmer.maker.skill/12)) end; table.insert(GrainFarmer.activeMaking,{id="grain_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainFarmer.completeMaking(m) local q=1.0+(GrainFarmer.getQualityBonus()/100); if GrainFarmer.maker then q=q+(GrainFarmer.maker.skill/180) end; q=math.min(2.0,q); GrainFarmer.productStock[m.productType]=(GrainFarmer.productStock[m.productType] or 0)+m.quantity; GrainFarmer.totalProducts=GrainFarmer.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainFarmer.maker then GrainFarmer.maker.itemsMade=GrainFarmer.maker.itemsMade+m.quantity; if math.random()<0.20 then GrainFarmer.maker.skill=math.min(100,GrainFarmer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žito pridelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grain.completed",{productName=m.productName,yield=m.yield}) end end
function GrainFarmer.update(dt) if not _G.state then return end; GrainFarmer.dayTimer=GrainFarmer.dayTimer+dt; if GrainFarmer.dayTimer>=30 then GrainFarmer.dayTimer=0; for i=#GrainFarmer.activeMaking,1,-1 do local m=GrainFarmer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainFarmer.completeMaking(m); table.remove(GrainFarmer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainFarmer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainFarmer.maker then tu=tu+10 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainFarmer.getStats() return {barleySeedStock=GrainFarmer.barleySeedStock,wheatSeedStock=GrainFarmer.wheatSeedStock,ryeSeedStock=GrainFarmer.ryeSeedStock,oatSeedStock=GrainFarmer.oatSeedStock,waterStock=GrainFarmer.waterStock,silverStock=GrainFarmer.silverStock,goldStock=GrainFarmer.goldStock,jewelStock=GrainFarmer.jewelStock,productStock=GrainFarmer.productStock,numBuildings=#GrainFarmer.buildings,hasMaker=GrainFarmer.maker~=nil,makerName=GrainFarmer.maker and GrainFarmer.maker.name or "—",makerSkill=GrainFarmer.maker and GrainFarmer.maker.skill or 0,activeMaking=#GrainFarmer.activeMaking,totalProducts=GrainFarmer.totalProducts} end
return GrainFarmer
